function cevniShow(k,b){document.querySelectorAll('#cevniPage .cevniSection').forEach(x=>x.classList.remove('active'));let e=document.getElementById('cevni'+k[0].toUpperCase()+k.slice(1));if(e)e.classList.add('active');document.querySelectorAll('#cevniPage>.cevniNav button').forEach(x=>x.classList.remove('active'));if(b)b.classList.add('active');if(k==='scenarios')cevniRenderScenario(0);}
function cevniDone(){try{return JSON.parse(localStorage.getItem('pwCevniDone')||'[]')}catch(e){return []}}
function cevniSaveDone(a){localStorage.setItem('pwCevniDone',JSON.stringify(a));cevniRenderModules()}
function cevniCurrentModule(){let d=cevniDone();for(let i=0;i<CEVNI_MODULES.length;i++)if(!d.includes(i))return i;return CEVNI_MODULES.length}
function cevniModuleUnlocked(i){return i<=cevniCurrentModule()||cevniDone().includes(i)}
function cevniRenderModules(){
 let d=cevniDone(),g=document.getElementById('cevniModuleGrid');if(!g)return;
 let current=cevniCurrentModule();
 g.innerHTML=CEVNI_MODULES.map((m,i)=>{let done=d.includes(i),cur=!done&&i===current,locked=!done&&!cur;let state=done?'COMPLETE':cur?'NEXT':'MODULE '+m.n;let note=done?'âœ“ Reviewed':cur?'Ready to continue':locked?'Course Mode locked':'Available';return `<button class="cvStage ${done?'done':''} ${cur?'current':''} ${locked?'locked':''}" ${locked?'disabled aria-disabled="true"':''} onclick="cevniOpenLesson(${i},0)"><span>${state}</span><b>${m.title}</b><small>${note}</small></button>`}).join('');
 let p=document.getElementById('cevniProgressText');if(p)p.textContent=`${d.length} / 9 MODULES REVIEWED â€¢ ${CEVNI_MODULES.reduce((n,m)=>n+m.sections.length,0)} TEACHING BRIEFINGS`;
}
function cevniOpenLesson(i,step=0){
 if(!cevniModuleUnlocked(i))return;
 let m=CEVNI_MODULES[i],a=document.getElementById('cevniLessonArea');if(!a)return;
 let total=m.sections.length,atCheck=step>=total,shown=Math.min(step+1,total),pct=atCheck?100:Math.round(shown/(total+1)*100);
 if(atCheck){
  a.innerHTML=`<div class="cvLessonShell"><div class="cvLessonTop"><div><div class="ver">MODULE ${m.n} â€¢ KNOWLEDGE CHECK</div><h2>${m.title}</h2><p class="cevniLead">Complete the module check after reviewing all ${total} teaching briefings.</p></div><div class="cvLessonCounter">CHECK â€¢ ${i+1} / 9</div></div><div class="cvLessonProgress"><i style="width:100%"></i></div><div class="cevniKnowledge cvKnowledgeOnly"><div class="ver">KNOWLEDGE CHECK â€¢ REQUIRED BEFORE REVIEW</div><h3>${m.check[0]}</h3><div class="cevniAnswers">${m.check[1].map((x,j)=>`<button onclick="cevniLessonAnswer(this,${j===m.check[2]},${i})">${String.fromCharCode(65+j)} â€¢ ${x}</button>`).join('')}</div><div id="cevniLessonFeedback"></div></div><div class="cvLessonNav"><button class="cvClose" onclick="cevniCloseLesson()">CLOSE</button><span></span><button class="cvBack" onclick="cevniOpenLesson(${i},${Math.max(0,total-1)})">â† LAST BRIEFING</button></div></div>`;
 }else{
  let x=m.sections[step];
  a.innerHTML=`<div class="cvLessonShell"><div class="cvLessonTop"><div><div class="ver">MODULE ${m.n} â€¢ GUIDED LEARNING</div><h2>${m.title}</h2><p class="cevniLead">${m.desc}</p></div><div class="cvLessonCounter">BRIEFING ${shown} / ${total}</div></div><div class="cvLessonProgress"><i style="width:${pct}%"></i></div><article class="cvBriefingCard"><span class="cvBriefNo">TEACHING BRIEFING ${String(shown).padStart(2,'0')}</span><h3>${x[0]}</h3><p>${x[1]}</p></article><div class="cvLessonNav"><button class="cvClose" onclick="cevniCloseLesson()">CLOSE</button>${step>0?`<button class="cvBack" onclick="cevniOpenLesson(${i},${step-1})">â† PREVIOUS</button>`:'<span></span>'}<button class="cvNext" onclick="cevniOpenLesson(${i},${step+1})">${step===total-1?'MODULE CHECK â†’':'NEXT BRIEFING â†’'}</button></div><div class="cvCourseFooter"><span>CEVNI course content remains separate from the COLREG pathway.</span><span>Module ${i+1} of 9</span></div></div>`;
 }
 a.scrollIntoView({behavior:'smooth',block:'start'});
}
function cevniCloseLesson(){let a=document.getElementById('cevniLessonArea');if(a)a.innerHTML=''}
function cevniLessonAnswer(b,ok,i){let box=document.getElementById('cevniLessonFeedback');document.querySelectorAll('#cevniLessonArea .cevniAnswers button').forEach(x=>x.disabled=true);b.classList.add(ok?'good':'bad');if(ok){box.innerHTML=`<div class="cevniPass"><b>UNDERSTOOD</b><p>Module check passed. Mark it reviewed and continue when ready.</p><button onclick="cevniMark(${i})">MARK REVIEWED & CONTINUE â†’</button></div>`}else{box.innerHTML=`<div class="cevniRetry"><b>REVIEW THAT POINT</b><p>The module stays open. Return to the teaching briefings, then retry the check.</p><button onclick="cevniOpenLesson(${i},0)">REVIEW MODULE</button><button onclick="cevniOpenLesson(${i},${CEVNI_MODULES[i].sections.length})">RETRY MODULE CHECK</button></div>`}}
function cevniMark(i){let d=cevniDone();if(!d.includes(i))d.push(i);cevniSaveDone(d);if(i<8)cevniOpenLesson(i+1,0);else document.getElementById('cevniLessonArea').innerHTML='<div class="cevniLesson"><h2>Pathway review complete.</h2><p>Continue through Signs, Sound and Practical, then take the 30-question mock.</p></div>'}
function cevniResetProgress(){if(confirm('Reset CEVNI pathway progress only?')){localStorage.removeItem('pwCevniDone');cevniRenderModules();cevniCloseLesson()}}
function cevniRenderSigns(){let g=document.getElementById('cevniSignGrid');if(!g)return;g.innerHTML=CEVNI_SIGNS.map(s=>`<div class="cevniSign"><div class="cevniPlate">${s.svg}</div><span class="cevniSignCode">ANNEX 7 â€¢ ${s.code}</span><span class="cevniSignMeaning">${s.meaning}</span><p class="cevniSignNote">${s.note}</p></div>`).join('')}
